<template>
  <div class="solutions">
    <Navbar :currentLang="currentLang" @change-lang="changeLang" />
    <section class="solutions-hero">
      <h1>{{ t.nav.solutions }}</h1>
      <p>{{ t.supplyChain.subtitle }}</p>
    </section>
    <section class="solutions-content">
      <div class="solutions-grid">
        <div v-for="(item, index) in t.businessModels.items" :key="index" class="solution-card">
          <h3>{{ item.title }}</h3>
          <p>{{ item.description }}</p>
        </div>
      </div>
    </section>
    <Footer :currentLang="currentLang" />
  </div>
</template>

<script>
import Navbar from '../components/Navbar.vue'
import Footer from '../components/Footer.vue'
import { languages } from '../assets/languages.js'

export default {
  name: 'Solutions',
  props: {
    currentLang: {
      type: String,
      default: 'zh'
    }
  },
  components: {
    Navbar,
    Footer
  },
  computed: {
    t() {
      return languages[this.currentLang] || languages.zh
    }
  },
  methods: {
    changeLang(lang) {
      this.$emit('change-lang', lang)
    }
  }
}
</script>

